ariants(product_id,sku,options,price_paise,mrp_paise,stock) SELECT d.id,d.sku,d.options,d.price,d.mrp,d.stock FROM data d JOIN inserted i ON i.id=d.id ON CONFLICT(sku) DO NOTHING;
